29	    },
30	    "source": {
31	      "type": "object",
32	      "additionalProperties": false,
33	      "required": ["type", "name"],
34	      "properties": {
35	        "type": {
36	          "type": "string",
37	          "enum": ["fizeau_runner", "external_leaderboard", "imported_report"]
38	        },
39	        "name": {
40	          "type": "string",
41	          "minLength": 1
42	        },
43	        "url": {
44	          "type": "string"
45	        },
46	        "artifact_path": {
47	          "type": "string"
48	        },
49	        "artifact_sha256": {
50	          "type": "string",
51	          "pattern": "^[a-f0-9]{64}$"
52	        },
53	        "notes": {
54	          "type": "array",
55	          "items": { "type": "string" }
56	        }
57	      }
58	    },
59	    "benchmark": {
60	      "type": "object",
61	      "additionalProperties": false,
62	      "required": ["name", "version"],
63	      "properties": {
64	        "name": {
65	          "type": "string",
66	          "examples": ["terminal-bench", "swe-bench", "humaneval", "mmlu", "tau-bench", "beadbench", "mhi"]
67	        },
68	        "version": {
69	          "type": "string",
70	          "minLength": 1
71	        },
72	        "dataset_commit": {
73	          "type": "string"
74	        },
75	        "dataset": {
76	          "type": "string"
77	        },
78	        "subset_id": {
79	          "type": "string"
80	        },
81	        "subset_version": {
82	          "type": "string"
83	        },
84	        "scorer": {
85	          "type": "string"
86	        },
87	        "scorer_version": {
88	          "type": "string"
89	        },
90	        "higher_is_better": {
91	          "type": "boolean",
92	          "default": true
93	        }
94	      }
95	    },
96	    "subject": {
97	      "type": "object",
98	      "additionalProperties": false,
99	      "required": ["model_raw", "harness", "provider"],
100	      "properties": {
101	        "model": {
102	          "type": "string",
103	          "description": "Canonical Fizeau catalog model id when known."
104	        },
105	        "model_raw": {
106	          "type": "string",
107	          "minLength": 1
108	        },
109	        "harness": {
110	          "type": "string",
111	          "minLength": 1
112	        },
113	        "provider": {
114	          "type": "string",
115	          "minLength": 1
116	        },
117	        "endpoint": {
118	          "type": "string"
119	        },
120	        "surface": {
121	          "type": "string"
122	        },
123	        "deployment_class": {
124	          "type": "string"
125	        },
126	        "reasoning": {
127	          "type": "string"
128	        },
129	        "sampling": {
130	          "type": "object",
131	          "additionalProperties": true
132	        }
133	      }
134	    },
135	    "scope": {
136	      "type": "object",
137	      "additionalProperties": false,
138	      "properties": {
